def get_competency_taxonomy_map_catalog() -> List[CompetencyTaxonomyMapRecord]:
    """Return complete competency_taxonomy_map registry."""
    return REGISTRY_COMPETENCY_TAXONOMY_MAP


def query_competency_taxonomy_map_by_difficulty(difficulty_level: str) -> List[CompetencyTaxonomyMapRecord]:
    """Filter competency_taxonomy_map elements matching difficulty."""
    return [item for item in REGISTRY_COMPETENCY_TAXONOMY_MAP if item.difficulty == difficulty_level]


def calculate_competency_taxonomy_map_total_weight() -> float:
    """Compute cumulative weighting of curriculum units."""
    return sum(item.weight for item in REGISTRY_COMPETENCY_TAXONOMY_MAP)

